import itertools
from itertools import combinations

def count_weak_quartets(adj, n):
    count = 0
    for nodes in combinations(range(n), 4):
        edges = 0
        for u, v in combinations(nodes, 2):
            if adj[u][v]:
                edges += 1
        if edges == 1:
            count += 1
    return count

def test_graphs(n):
    max_wq = 0
    # Disjoint edges
    for m in range(1, n // 2 + 1):
        adj = [[0]*n for _ in range(n)]
        for i in range(m):
            adj[2*i][2*i+1] = adj[2*i+1][2*i] = 1
        wq = count_weak_quartets(adj, n)
        max_wq = max(max_wq, wq)
    return max_wq

for n in range(4, 11):
    print(f"n={n}, max_wq={test_graphs(n)}")

